function TradeCardWatcher() {
  const { toast } = useApp();
  const orders=useStore(s=>s.invest.orders);
  const invest=useStore(s=>s.invest);
  const discordOn=useStore(s=>s.learnAlert.discord&&s.learnAlert.discordConsent);
  const observed=useRef<Set<string>|null>(null);
  const inFlight=useRef(new Set<string>());
  useEffect(()=>{
    if(!observed.current){observed.current=new Set(orders.filter(o=>o.status==='filled').map(o=>o.id));return;}
    const fresh=orders.filter(o=>o.status==='filled'&&o.side==='buy'&&!observed.current!.has(o.id)&&!inFlight.current.has(o.id));
    for(const order of fresh){
      inFlight.current.add(order.id);
      const code=stockByName(order.name)?.code;
      if(!code){observed.current.add(order.id);inFlight.current.delete(order.id);continue;}
      const totalAssets=invest.cash+Object.entries(invest.holdings).reduce((sum,[name,qty])=>sum+qty*livePrice(name),0);
      const positionValue=(invest.holdings[order.name]||0)*livePrice(order.name);
      const lesson=lessonById(stockLessonId(code))||lessonById('etf')!;
      void sendTradeCard({tradeId:order.id,name:order.name,side:'buy',shares:order.shares,price:order.price,
        filledAt:Date.parse(order.filledAt||order.at),autoSend:discordOn,holdingQty:invest.holdings[order.name]||0,holdingAvg:invest.avgPrice[order.name],weightPct:totalAssets>0?Math.min(100,positionValue/totalAssets*100):0,
        lesson:{title:lesson.title,points:lesson.cards.slice(0,3).map(c=>c.title)},
      }).then(result=>{
        if(result.ok){observed.current!.add(order.id);toast(discordOn?'카드뉴스 4장을 만들고 Discord로 전송을 요청했어요':'카드뉴스 4장을 만들었어요. 금융 카드뉴스에서 확인해요','notifications');}
        else toast('카드뉴스 요청 실패: '+result.error,'error');
      }).finally(()=>inFlight.current.delete(order.id));
    }
  },[orders,discordOn,toast,invest]);
  return null;
}

